// Intrinsic (shared) state
class CharacterStyle {
  constructor(public font: string, public size: number, public color: string) {}
}

class StyleFactory {
  private static styles = new Map<string, CharacterStyle>();

  static get(font: string, size: number, color: string): CharacterStyle {
    const key = `${font}-${size}-${color}`;
    if (!this.styles.has(key)) {
      this.styles.set(key, new CharacterStyle(font, size, color));
    }
    return this.styles.get(key)!; // shared across every matching character
  }
}

// Extrinsic (unique) state stays separate and cheap
class Character {
  constructor(public char: string, public style: CharacterStyle, public x: number, public y: number) {}
}

const sharedStyle = StyleFactory.get("Arial", 12, "black");
const doc = text.split("").map((c, i) => new Character(c, sharedStyle, i, 0));
